// Тикеты, принятые 14.10.2026 (iPhone, TestFlight 1.0.0 (20), вход клиента):
//   #6cfcbcb7 · 6cfcbcb774ecddfef579e779 — карточка «תאריכים חשובים» RTL (Figma 436:1292):
//     «התאריך העברי בצד ימין, ושם התאריך והתאריך הלועזי מיושרים לימין וצמודים אליו … העיפרון בצד שמאל.»
//     Факт 14.10: имя и григорианская дата справа рядом с бейджем еврейской даты (6cfcbcb7-ios-b20-date-card-rtl.png).
//   #9bc6265b · 9bc6265b0d26bbb2b017a126 — «עריכת תאריך» → «מחיקת התאריך» → окно «למחוק את התאריך?» («ביטול»/«מחיקה»),
//     текст ««<имя>» יימחק מהתאריכים החשובים שלך, ואי אפשר יהיה לשחזר אותו.»; «מחיקה» удаляет запись
//     (источник текста — принятый #7b04425b / ID-02 web; факт iOS 14.10: 9bc6265b-ios-b20-delete-confirm-dialog.png, -deleted.png).
// Кейсы .qa/tests/important-dates/ID-06-date-card-rtl.md, ID-07-delete-date-confirm.md.
// @data: создаёт временную запись «QA-AUTO-מחיקה-NNNN» на сегодня и удаляет её (ID-06c — это и проверка, и уборка; страховка — after).
// Чужие записи (у клиента — «בדיקת QA») НЕ трогаем: проверяем, что после удаления они на месте.
// Все нажатия — по элементу: окно «עריכת תאריך» заходит под строку статуса (#36a75b77) — «סגירה» только по label.
import { $$, driver, expect } from '@wdio/globals';
import { byText, byTextContains, byLabel, tapLabel, tapText, allByText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { dotDate, isoDate } from '../../../e2e/tests/_helpers/dates.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';
import { rectOf, staticText, type Rect } from '../_lib/app-1310.ts';
import { homeHebrewDate, homeDates, scrollToDateCard, tryDeleteDate } from '../_lib/app-1310b.ts';
import { addImportantDateToday, openDeleteDialog, dateExists, DELETE_TITLE, deleteBody, labelOf } from '../_lib/app-1410.ts';

const NAME = `QA-AUTO-מחיקה-${String(Date.now()).slice(-4)}`;
let created = false;

/** Ближайший к строке y видимый текст (для даты «DD.MM.YYYY» и месяца бейджа — у других карточек те же тексты). */
async function nearestText(text: string, y: number): Promise<Rect | null> {
  let best: Rect | null = null; let bestD = Infinity;
  for (const el of await allByText(text)) {
    if (!(await el.isDisplayed().catch(() => false))) continue;
    const r = await rectOf(el);
    const d = Math.abs(r.y + r.height / 2 - y);
    if (d < bestD && d <= 90) { bestD = d; best = r; }
  }
  return best;
}

/** Другие записи, кроме временной (на аккаунте клиента — «בדיקת QA»): подписи кнопок «<имя>: פתיחה לעריכה». */
async function otherDateLabels(): Promise<string[]> {
  await toHome();
  await homeDates();
  const out: string[] = [];
  const els = driver.isAndroid
    ? await $$('android=new UiSelector().descriptionMatches(".*: פתיחה לעריכה")').getElements()
    : await $$('-ios predicate string:name ENDSWITH ": פתיחה לעריכה"').getElements();
  for (const el of els) { const l = await labelOf(el); if (l && !l.startsWith('QA-AUTO-')) out.push(l); }
  return out;
}

describe('«תאריכים חשובים»: карточка RTL и удаление с подтверждением (#6cfcbcb7 #9bc6265b)', () => {
  let others: string[] = [];
  afterEach(async () => { await toHome().catch(() => {}); });
  after(async () => {
    if (created && (await dateExists(NAME).catch(() => false))) await tryDeleteDate(NAME).catch(() => {});
  });

  it('ID-06a Карточка: бейдж еврейской даты справа, имя и «DD.MM.YYYY» справа вплотную к нему, карандаш слева #6cfcbcb7 @data', async () => {
    others = await otherDateLabels();
    const header = await homeHebrewDate();
    const now = new Date();
    const edit = await addImportantDateToday(NAME, isoDate(now));
    created = true;
    const { width } = await driver.getWindowSize();

    const nameEl = staticText(NAME);
    if (!(await shown(nameEl))) {
      console.log('[ID-06a] имя — часть склеенной подписи карточки, рамки нет — @manual-check по скрину 6cfcbcb7-ios-b20-date-card-rtl.png');
      return;
    }
    const n = await rectOf(nameEl);
    const ny = n.y + n.height / 2;
    const date = await nearestText(dotDate(now), ny + n.height);
    const month = await nearestText(header.month, ny);
    console.log(`[ID-06a] имя ${JSON.stringify(n)}, дата ${JSON.stringify(date)}, месяц бейджа ${JSON.stringify(month)}`);

    // Имя — в правой части, если рамка не на всю ширину (иначе позиция букв не видна).
    if (n.width < width * 0.6) {
      expect(n.x + n.width).toBeGreaterThan(width * 0.6);
      if (month) {
        const gap = month.x - (n.x + n.width);
        expect({ gapToBadge: gap >= -4 && gap <= 48 }).toEqual({ gapToBadge: true });   // вплотную к бейджу (14.10 ≈ 15 pt)
      }
      if (date && date.width < width * 0.6) expect(Math.abs(date.x + date.width - (n.x + n.width))).toBeLessThanOrEqual(8);
    } else {
      console.log('[ID-06a] рамка имени почти на всю ширину — выравнивание @manual-check');
    }
    // Бейдж справа.
    if (month) expect(month.x + month.width / 2).toBeGreaterThan(width * 0.7);
    // Карандаш слева (если кнопка правки — отдельная иконка, а не вся карточка).
    const e = await rectOf(edit);
    if (e.width < width * 0.5) expect(e.x + e.width / 2).toBeLessThan(width / 2);
  });

  it('ID-06b «מחיקת התאריך» → окно «למחוק את התאריך?» с текстом; «ביטול» — запись остаётся #9bc6265b @data', async function () {
    if (!created) skipWith(this, 'временная запись не создана');
    await homeDates();
    await openDeleteDialog(NAME);
    await expect(byText(DELETE_TITLE)).toBeDisplayed();
    await expect(byTextContains(deleteBody(NAME))).toBeDisplayed();
    await expect(byText('ביטול')).toBeDisplayed();
    await expect(byText('מחיקה')).toBeDisplayed();
    await tapText('ביטול');
    await expect(byText(DELETE_TITLE)).not.toBeDisplayed({ wait: 10000 });
    // Окно правки (если осталось) закрыть по элементу «סגירה».
    if (await byText('עריכת תאריך').isDisplayed().catch(() => false)) await tapLabel('סגירה');
    expect(await dateExists(NAME)).toBe(true);
  });

  it('ID-06c «מחיקה» удаляет запись (и после перезапуска её нет); другие записи на месте #9bc6265b @data @cleanup', async function () {
    if (!created) skipWith(this, 'временная запись не создана');
    await homeDates();
    await openDeleteDialog(NAME);
    await tapText('מחיקה');
    await expect(byText(DELETE_TITLE)).not.toBeDisplayed({ wait: 10000 });
    await driver.waitUntil(async () => !(await shown(byLabel(`${NAME}: פתיחה לעריכה`))), { timeout: 15000, timeoutMsg: `«${NAME}» не исчезла после «מחיקה»` });

    // Перезапуск приложения — записи нет (удаление сохранено, не только скрыто).
    const id = driver.isAndroid ? process.env.APP_ANDROID_PACKAGE : process.env.APP_IOS_BUNDLE;
    if (id) { await driver.terminateApp(id); await driver.activateApp(id); await (await byText('בית')).waitForDisplayed({ timeout: 30000 }); }
    expect(await dateExists(NAME)).toBe(false);
    created = false;

    // Чужие записи (у клиента — «בדיקת QA») не тронуты.
    for (const l of others) {
      await homeDates();
      expect({ label: l, present: Boolean(await scrollToDateCard(l.replace(/: פתיחה לעריכה$/, '')).catch(() => null)) }).toEqual({ label: l, present: true });
    }
  });
});
